  ('Geography', 'hard', 3, 'mcq', 'Which country is home to the ancient ruins of Petra?', '[{"id": "A", "text": "Egypt"}, {"id": "B", "text": "Israel"}, {"id": "C", "text": "Syria"}, {"id": "D", "text": "Jordan"}]'::jsonb, 3, 'bank', 'active', 0.750, 'Petra is a famous archaeological city in southern Jordan.'),
  ('Geography', 'hard', 3, 'mcq', 'What is the name of the archipelago where Darwin developed his theory of evolution?', '[{"id": "A", "text": "Canary Islands"}, {"id": "B", "text": "Maldives"}, {"id": "C", "text": "Galapagos Islands"}, {"id": "D", "text": "Hawaiian Islands"}]'::jsonb, 2, 'bank', 'active', 0.750, 'Charles Darwin made key observations on the Galapagos Islands that informed his theory of evolution.'),
  ('Geography', 'hard', 3, 'mcq', 'Which country has the largest economy in Africa?', '[{"id": "A", "text": "South Africa"}, {"id": "B", "text": "Kenya"}, {"id": "C", "text": "Ethiopia"}, {"id": "D", "text": "Nigeria"}]'::jsonb, 3, 'bank', 'active', 0.750, 'Nigeria has the largest economy in Africa by GDP.'),
  ('Science', 'easy', 1, 'mcq', 'What is the most abundant gas in Earth''s atmosphere?', '[{"id": "A", "text": "Oxygen"}, {"id": "B", "text": "Carbon Dioxide"}, {"id": "C", "text": "Argon"}, {"id": "D", "text": "Nitrogen"}]'::jsonb, 3, 'bank', 'active', 0.750, 'Nitrogen makes up approximately 78% of Earth''s atmosphere.'),
  ('Science', 'easy', 1, 'mcq', 'What is the speed of light in a vacuum?', '[{"id": "A", "text": "300,000 km/s"}, {"id": "B", "text": "150,000 km/s"}, {"id": "C", "text": "450,000 km/s"}, {"id": "D", "text": "600,000 km/s"}]'::jsonb, 0, 'bank', 'active', 0.750, 'Light travels at approximately 299,792 km/s (about 300,000 km/s) in a vacuum.'),
  ('Science', 'easy', 1, 'mcq', 'What is the powerhouse of the cell?', '[{"id": "A", "text": "Nucleus"}, {"id": "B", "text": "Ribosome"}, {"id": "C", "text": "Endoplasmic reticulum"}, {"id": "D", "text": "Mitochondria"}]'::jsonb, 3, 'bank', 'active', 0.750, 'Mitochondria produce ATP (energy) through cellular respiration.'),
  ('Science', 'easy', 1, 'mcq', 'What is the chemical formula for water?', '[{"id": "A", "text": "HO"}, {"id": "B", "text": "H2O"}, {"id": "C", "text": "H2O2"}, {"id": "D", "text": "H3O"}]'::jsonb, 1, 'bank', 'active', 0.750, 'Water consists of two hydrogen atoms and one oxygen atom (H₂O).'),
  ('Science', 'easy', 1, 'mcq', 'Which planet is closest to the Sun?', '[{"id": "A", "text": "Venus"}, {"id": "B", "text": "Earth"}, {"id": "C", "text": "Mars"}, {"id": "D", "text": "Mercury"}]'::jsonb, 3, 'bank', 'active', 0.750, 'Mercury is the closest planet to the Sun, orbiting at an average distance of 58 million km.'),
  ('Science', 'easy', 1, 'mcq', 'What is the atomic number of carbon?', '[{"id": "A", "text": "4"}, {"id": "B", "text": "6"}, {"id": "C", "text": "8"}, {"id": "D", "text": "12"}]'::jsonb, 1, 'bank', 'active', 0.750, 'Carbon has an atomic number of 6, meaning it has 6 protons in its nucleus.'),
  ('Science', 'easy', 1, 'mcq', 'What is the process by which plants make food using sunlight?', '[{"id": "A", "text": "Respiration"}, {"id": "B", "text": "Transpiration"}, {"id": "C", "text": "Fermentation"}, {"id": "D", "text": "Photosynthesis"}]'::jsonb, 3, 'bank', 'active', 0.750, 'Photosynthesis uses sunlight, CO₂, and water to produce glucose and oxygen.'),
  ('Science', 'easy', 1, 'mcq', 'What is Newton''s first law of motion?', '[{"id": "A", "text": "F=ma"}, {"id": "B", "text": "Objects in motion stay in motion unless acted upon by an external force"}, {"id": "C", "text": "Energy cannot be created or destroyed"}, {"id": "D", "text": "Every action has an equal and opposite reaction"}]'::jsonb, 1, 'bank', 'active', 0.750, 'Newton''s first law is the law of inertia — objects continue in their state unless a net force acts on them.'),
  ('Science', 'easy', 1, 'mcq', 'What is the half-life of Carbon-14?', '[{"id": "A", "text": "1,000 years"}, {"id": "B", "text": "5,730 years"}, {"id": "C", "text": "10,000 years"}, {"id": "D", "text": "50,000 years"}]'::jsonb, 1, 'bank', 'active', 0.750, 'Carbon-14 has a half-life of approximately 5,730 years, used in radiocarbon dating.'),
  ('Science', 'easy', 1, 'mcq', 'Which organ in the human body produces insulin?', '[{"id": "A", "text": "Liver"}, {"id": "B", "text": "Kidney"}, {"id": "C", "text": "Stomach"}, {"id": "D", "text": "Pancreas"}]'::jsonb, 3, 'bank', 'active', 0.750, 'The pancreas produces insulin to regulate blood sugar levels.'),
  ('Science', 'easy', 1, 'mcq', 'What is DNA?', '[{"id": "A", "text": "A type of protein"}, {"id": "B", "text": "A molecule carrying genetic information"}, {"id": "C", "text": "A cellular organelle"}, {"id": "D", "text": "A type of RNA"}]'::jsonb, 1, 'bank', 'active', 0.750, 'DNA (deoxyribonucleic acid) is a molecule that carries genetic instructions for development and function.'),
  ('Science', 'easy', 1, 'mcq', 'What is the periodic table''s symbol for gold?', '[{"id": "A", "text": "Ag"}, {"id": "B", "text": "Go"}, {"id": "C", "text": "Gd"}, {"id": "D", "text": "Au"}]'::jsonb, 3, 'bank', 'active', 0.750, 'Gold''s symbol Au comes from the Latin word ''aurum''.'),
  ('Science', 'easy', 1, 'mcq', 'Which scientist developed the theory of general relativity?', '[{"id": "A", "text": "Isaac Newton"}, {"id": "B", "text": "Niels Bohr"}, {"id": "C", "text": "Stephen Hawking"}, {"id": "D", "text": "Albert Einstein"}]'::jsonb, 3, 'bank', 'active', 0.750, 'Albert Einstein published the theory of general relativity in 1915.'),
  ('Science', 'easy', 1, 'mcq', 'What is the name of the force that keeps planets in orbit around the Sun?', '[{"id": "A", "text": "Electromagnetic force"}, {"id": "B", "text": "Nuclear force"}, {"id": "C", "text": "Centrifugal force"}, {"id": "D", "text": "Gravity"}]'::jsonb, 3, 'bank', 'active', 0.750, 'Gravity is the force that keeps planets in elliptical orbits around the Sun.'),
  ('Science', 'easy', 1, 'mcq', 'What is the process of a liquid turning into a gas?', '[{"id": "A", "text": "Condensation"}, {"id": "B", "text": "Sublimation"}, {"id": "C", "text": "Melting"}, {"id": "D", "text": "Evaporation"}]'::jsonb, 3, 'bank', 'active', 0.750, 'Evaporation is the process by which a liquid converts to its gaseous state.'),
  ('Science', 'easy', 1, 'mcq', 'Which element has the chemical symbol ''O''?', '[{"id": "A", "text": "Osmium"}, {"id": "B", "text": "Oganesson"}, {"id": "C", "text": "Osmium"}, {"id": "D", "text": "Oxygen"}]'::jsonb, 3, 'bank', 'active', 0.750, 'O is the symbol for Oxygen on the periodic table.'),
  ('Science', 'easy', 1, 'mcq', 'How many chromosomes do humans normally have?', '[{"id": "A", "text": "23"}, {"id": "B", "text": "44"}, {"id": "C", "text": "46"}, {"id": "D", "text": "48"}]'::jsonb, 2, 'bank', 'active', 0.750, 'Humans normally have 46 chromosomes arranged in 23 pairs.'),
  ('Science', 'medium', 2, 'mcq', 'What is the term for an organism that makes its own food?', '[{"id": "A", "text": "Heterotroph"}, {"id": "B", "text": "Decomposer"}, {"id": "C", "text": "Consumer"}, {"id": "D", "text": "Autotroph"}]'::jsonb, 3, 'bank', 'active', 0.750, 'Autotrophs (like plants) produce their own food through photosynthesis or chemosynthesis.'),
  ('Science', 'medium', 2, 'mcq', 'What is the most abundant element in the universe?', '[{"id": "A", "text": "Helium"}, {"id": "B", "text": "Oxygen"}, {"id": "C", "text": "Carbon"}, {"id": "D", "text": "Hydrogen"}]'::jsonb, 3, 'bank', 'active', 0.750, 'Hydrogen makes up approximately 75% of all normal matter in the universe by mass.'),
  ('Science', 'medium', 2, 'mcq', 'What is the name of the closest star to Earth besides the Sun?', '[{"id": "A", "text": "Betelgeuse"}, {"id": "B", "text": "Sirius"}, {"id": "C", "text": "Proxima Centauri"}, {"id": "D", "text": "Vega"}]'::jsonb, 2, 'bank', 'active', 0.750, 'Proxima Centauri is the nearest star to our solar system at 4.24 light-years away.'),
  ('Science', 'medium', 2, 'mcq', 'What is the pH level of pure water?', '[{"id": "A", "text": "5"}, {"id": "B", "text": "6"}, {"id": "C", "text": "7"}, {"id": "D", "text": "8"}]'::jsonb, 2, 'bank', 'active', 0.750, 'Pure water has a neutral pH of 7.'),
  ('Science', 'medium', 2, 'mcq', 'Which type of rock is formed from cooled magma?', '[{"id": "A", "text": "Sedimentary"}, {"id": "B", "text": "Metamorphic"}, {"id": "C", "text": "Limestone"}, {"id": "D", "text": "Igneous"}]'::jsonb, 3, 'bank', 'active', 0.750, 'Igneous rocks form when magma or lava cools and solidifies.'),
  ('Science', 'medium', 2, 'mcq', 'What is the name of the scale used to measure earthquake magnitude?', '[{"id": "A", "text": "Beaufort Scale"}, {"id": "B", "text": "Fujita Scale"}, {"id": "C", "text": "Richter Scale"}, {"id": "D", "text": "Mohs Scale"}]'::jsonb, 2, 'bank', 'active', 0.750, 'The Richter Scale (now Moment Magnitude Scale) measures the energy released by earthquakes.'),
  ('Science', 'medium', 2, 'mcq', 'How many bones are in the adult human body?', '[{"id": "A", "text": "186"}, {"id": "B", "text": "196"}, {"id": "C", "text": "206"}, {"id": "D", "text": "216"}]'::jsonb, 2, 'bank', 'active', 0.750, 'The adult human body has 206 bones.'),
  ('Science', 'medium', 2, 'mcq', 'What is the term for the bending of light as it passes from one medium to another?', '[{"id": "A", "text": "Reflection"}, {"id": "B", "text": "Diffraction"}, {"id": "C", "text": "Absorption"}, {"id": "D", "text": "Refraction"}]'::jsonb, 3, 'bank', 'active', 0.750, 'Refraction is the bending of light when it passes between mediums of different densities.'),
  ('Science', 'medium', 2, 'mcq', 'Which planet has the most moons in our solar system?', '[{"id": "A", "text": "Jupiter"}, {"id": "B", "text": "Uranus"}, {"id": "C", "text": "Neptune"}, {"id": "D", "text": "Saturn"}]'::jsonb, 3, 'bank', 'active', 0.750, 'Saturn has the most confirmed moons with 146, surpassing Jupiter''s 95.'),
  ('Science', 'medium', 2, 'mcq', 'What is the term for a substance that speeds up a chemical reaction without being consumed?', '[{"id": "A", "text": "Inhibitor"}, {"id": "B", "text": "Solvent"}, {"id": "C", "text": "Catalyst"}, {"id": "D", "text": "Reactant"}]'::jsonb, 2, 'bank', 'active', 0.750, 'A catalyst increases the rate of a chemical reaction without being permanently altered.'),
  ('Science', 'medium', 2, 'mcq', 'What is the name of the boundary between Earth''s crust and mantle?', '[{"id": "A", "text": "Gutenberg discontinuity"}, {"id": "B", "text": "Conrad discontinuity"}, {"id": "C", "text": "Mohorovi\u010di\u0107 discontinuity"}, {"id": "D", "text": "Lehmann discontinuity"}]'::jsonb, 2, 'bank', 'active', 0.750, 'The Mohorovičić discontinuity (Moho) marks the boundary between Earth''s crust and mantle.'),
  ('Science', 'medium', 2, 'mcq', 'Which gas is primarily responsible for the greenhouse effect?', '[{"id": "A", "text": "Oxygen"}, {"id": "B", "text": "Nitrogen"}, {"id": "C", "text": "Argon"}, {"id": "D", "text": "Carbon Dioxide"}]'::jsonb, 3, 'bank', 'active', 0.750, 'Carbon dioxide (CO₂) is the primary greenhouse gas driving human-caused climate change.'),
  ('Science', 'medium', 2, 'mcq', 'What is the name of the force that opposes the relative motion of two surfaces?', '[{"id": "A", "text": "Tension"}, {"id": "B", "text": "Normal force"}, {"id": "C", "text": "Gravity"}, {"id": "D", "text": "Friction"}]'::jsonb, 3, 'bank', 'active', 0.750, 'Friction is the force that resists the sliding of surfaces against each other.'),
  ('Science', 'medium', 2, 'mcq', 'What is the function of red blood cells?', '[{"id": "A", "text": "Fight infection"}, {"id": "B", "text": "Produce antibodies"}, {"id": "C", "text": "Aid in clotting"}, {"id": "D", "text": "Transport oxygen"}]'::jsonb, 3, 'bank', 'active', 0.750, 'Red blood cells carry oxygen from the lungs to tissues throughout the body.'),
  ('Science', 'medium', 2, 'mcq', 'Which subatomic particle has a negative charge?', '[{"id": "A", "text": "Neutron"}, {"id": "B", "text": "Proton"}, {"id": "C", "text": "Positron"}, {"id": "D", "text": "Electron"}]'::jsonb, 3, 'bank', 'active', 0.750, 'Electrons carry a negative electrical charge.'),
  ('Science', 'medium', 2, 'mcq', 'What is the chemical symbol for iron?', '[{"id": "A", "text": "Ir"}, {"id": "B", "text": "In"}, {"id": "C", "text": "Fi"}, {"id": "D", "text": "Fe"}]'::jsonb, 3, 'bank', 'active', 0.750, 'Iron''s symbol Fe comes from the Latin word ''ferrum''.'),
  ('Science', 'medium', 2, 'mcq', 'What is the name of the longest bone in the human body?', '[{"id": "A", "text": "Tibia"}, {"id": "B", "text": "Humerus"}, {"id": "C", "text": "Spine"}, {"id": "D", "text": "Femur"}]'::jsonb, 3, 'bank', 'active', 0.750, 'The femur (thigh bone) is the longest and strongest bone in the human body.'),
  ('Science', 'medium', 2, 'mcq', 'What is the name of the process by which a caterpillar becomes a butterfly?', '[{"id": "A", "text": "Mitosis"}, {"id": "B", "text": "Metamorphosis"}, {"id": "C", "text": "Meiosis"}, {"id": "D", "text": "Molting"}]'::jsonb, 1, 'bank', 'active', 0.750, 'Metamorphosis is the biological process of transformation from larva to adult form.'),
  ('Science', 'hard', 3, 'mcq', 'Which vitamin is produced by the body when exposed to sunlight?', '[{"id": "A", "text": "Vitamin A"}, {"id": "B", "text": "Vitamin B12"}, {"id": "C", "text": "Vitamin C"}, {"id": "D", "text": "Vitamin D"}]'::jsonb, 3, 'bank', 'active', 0.750, 'The skin synthesizes Vitamin D when exposed to ultraviolet B (UVB) radiation from sunlight.'),
  ('Science', 'hard', 3, 'mcq', 'What type of energy does the Sun primarily emit?', '[{"id": "A", "text": "Nuclear energy"}, {"id": "B", "text": "Chemical energy"}, {"id": "C", "text": "Electrical energy"}, {"id": "D", "text": "Electromagnetic (light) energy"}]'::jsonb, 3, 'bank', 'active', 0.750, 'The Sun primarily emits electromagnetic radiation including visible light and infrared energy.'),
  ('Science', 'hard', 3, 'mcq', 'What is the name of the scale used to measure hardness of minerals?', '[{"id": "A", "text": "Richter Scale"}, {"id": "B", "text": "Beaufort Scale"}, {"id": "C", "text": "Mohs Hardness Scale"}, {"id": "D", "text": "pH Scale"}]'::jsonb, 2, 'bank', 'active', 0.750, 'The Mohs Hardness Scale ranks minerals from 1 (talc) to 10 (diamond).'),
  ('Science', 'hard', 3, 'mcq', 'What is the study of heredity and variation in living organisms?', '[{"id": "A", "text": "Ecology"}, {"id": "B", "text": "Biochemistry"}, {"id": "C", "text": "Physiology"}, {"id": "D", "text": "Genetics"}]'::jsonb, 3, 'bank', 'active', 0.750, 'Genetics is the branch of biology concerned with genes, heredity, and genetic variation.'),
  ('Science', 'hard', 3, 'mcq', 'Which law states that energy cannot be created or destroyed?', '[{"id": "A", "text": "Newton''s First Law"}, {"id": "B", "text": "Ohm''s Law"}, {"id": "C", "text": "First Law of Thermodynamics"}, {"id": "D", "text": "Boyle''s Law"}]'::jsonb, 2, 'bank', 'active', 0.750, 'The First Law of Thermodynamics states that energy can only be transferred or transformed, not created or destroyed.'),
  ('Science', 'hard', 3, 'mcq', 'What is the name of the organ that filters blood in the human body?', '[{"id": "A", "text": "Liver"}, {"id": "B", "text": "Spleen"}, {"id": "C", "text": "Pancreas"}, {"id": "D", "text": "Kidney"}]'::jsonb, 3, 'bank', 'active', 0.750, 'The kidneys filter blood, removing waste products and excess substances as urine.'),
  ('Science', 'hard', 3, 'mcq', 'What is a black hole?', '[{"id": "A", "text": "A region of space where matter is very cold"}, {"id": "B", "text": "A collapsed star with gravity so strong light cannot escape"}, {"id": "C", "text": "An empty void in space"}, {"id": "D", "text": "A supernova remnant"}]'::jsonb, 1, 'bank', 'active', 0.750, 'A black hole is a region of spacetime where gravity is so strong that nothing, not even light, can escape.'),
